    {
      "hunk_id": "H059",
      "decision": "SOL",
      "reason": "SOL keeps Jin Taekyung as the Emperor’s battering ram."
    },
    {
      "hunk_id": "H060",
      "decision": "BASE",
      "reason": "SOL says the rebels wield supernatural powers, where the source says they dare defy the order and seek to wield them."
    },
    {
      "hunk_id": "H061",
      "decision": "BASE",
      "reason": "“Shaking” replaces the source’s image of the name resounding across the regions."
    },
    {
      "hunk_id": "H062",
      "decision": "SOL",
      "reason": "SOL preserves his two public roles and the Great General’s work putting down traitors."
    },
    {
      "hunk_id": "H063",
      "decision": "SOL",
      "reason": "SOL keeps the contrast between martial artist and Emperor-appointed marquis."
    },
    {
      "hunk_id": "H064",
      "decision": "SOL",
      "reason": "SOL preserves the unprecedented appointment and his fight to end the chaotic age."
    },
    {
      "hunk_id": "H065",
      "decision": "SOL",
      "reason": "SOL keeps the repeated victory."
    },
    {
      "hunk_id": "H066",
      "decision": "SOL",
      "reason": "The source praises the Emperor’s reign without explicitly calling it wise; SOL avoids that addition."
    },
    {
      "hunk_id": "H067",
      "decision": "BASE",
      "reason": "SOL softens the explicit insistence on getting drunk to merely having a drink."
    },
    {
      "hunk_id": "H068",
      "decision": "SOL",
      "reason": "SOL preserves the story’s embellishment and the undeniable victory."
    },
    {
      "hunk_id": "H069",
      "decision": "SOL",
      "reason": "SOL keeps the packed taverns, revelers spilling outside, and toast to Gansu’s victory."
    },
    {
      "hunk_id": "H070",
      "decision": "SOL",
      "reason": "SOL preserves the praise, thanks, and relief without BASE’s awkward “as one.”"
    },
    {
      "hunk_id": "H071",
      "decision": "SOL",
      "reason": "SOL keeps the tentative hope that the war will end soon with little harm."
    },
    {
      "hunk_id": "H072",
      "decision": "BASE",
      "reason": "SOL drops the source’s urging to hurry."
    },
    {
      "hunk_id": "H073",
      "decision": "BASE",
      "reason": "SOL adds “all of it,” intensifying the instruction beyond the source."
    },
    {
      "hunk_id": "H074",
      "decision": "SOL",
      "reason": "SOL preserves the laughter, feasts, and absence of fear."
    },
    {
      "hunk_id": "H075",
      "decision": "SOL",
      "reason": "SOL carries the martial artists and common folk into the next sentence without losing the contrast."
    },
    {
      "hunk_id": "H076",
      "decision": "SOL",
      "reason": "SOL keeps both groups laughing and celebrating their victory."
    },
    {
      "hunk_id": "H077",
      "decision": "SOL",
      "reason": "SOL preserves the one-day qualification and the ominous pause."
    },
    {
      "hunk_id": "H078",
      "decision": "SOL",
      "reason": "SOL keeps the falcon’s origin in Qinghai’s distant western frontier and its weary arrival."
    },
    {
      "hunk_id": "H079",
      "decision": "BASE",
      "reason": "SOL drops that the forgotten dream was from the previous night."
    },
    {
      "hunk_id": "H080",
      "decision": "SOL",
      "reason": "“Exciting story” keeps the imagined appeal of the dream."
    },
    {
      "hunk_id": "H081",
      "decision": "SOL",
      "reason": "SOL folds the learning transition into the next sentence."
    },
    {
      "hunk_id": "H082",
      "decision": "SOL",
      "reason": "SOL keeps the link between forgetting a dream and avoiding a nightmare’s lingering feeling."
    },
    {
      "hunk_id": "H083",
      "decision": "SOL",
      "reason": "SOL preserves that forgetting did not mean the nightmare never happened."
    },
    {
      "hunk_id": "H084",
      "decision": "SOL",
      "reason": "SOL keeps the waking, swaying saddle, Hyuk Mujin, and the offered cloth."
    },
    {
      "hunk_id": "H085",
      "decision": "BASE",
      "reason": "“What’s this?” matches the question about the cloth; SOL instead asks its purpose."
    },
    {
      "hunk_id": "H086",
      "decision": "SOL",
      "reason": "SOL keeps the dry retort and refusal to wipe him down."
    },
    {
      "hunk_id": "H087",
      "decision": "SOL",
      "reason": "SOL preserves the vivid feeling of wet clothes clinging to him and the cold sweat."
    },
    {
      "hunk_id": "H088",
      "decision": "BASE",
      "reason": "SOL adds “what it was,” spelling out the terse “I know” thought."
    },
    {
      "hunk_id": "H089",
      "decision": "SOL",
      "reason": "SOL naturally identifies the two categories as kinds of people appearing in his nightmares."
    },
    {
      "hunk_id": "H090",
      "decision": "SOL",
      "reason": "SOL keeps the people’s deaths caused by his failure to save them."
    },
    {
      "hunk_id": "H091",
      "decision": "SOL",
      "reason": "SOL preserves the contrast with people killed by his own hand."
    },
    {
      "hunk_id": "H092",
      "decision": "BASE",
      "reason": "SOL’s “again” implies recurrence; the source says another kind was added after a long time."
    },
    {
      "hunk_id": "H093",
      "decision": "BASE",
      "reason": "SOL moves the strange, unexplained dreams into this line instead of preserving the sudden recollection."
    },
    {
      "hunk_id": "H094",
      "decision": "BASE",
      "reason": "SOL deletes the distinct image of a strange, unidentified dream."
    },
    {
      "hunk_id": "H095",
      "decision": "SOL",
      "reason": "SOL preserves both identities and the memories of the Taiyuan Jin Taekyung’s past."
    },
    {
      "hunk_id": "H096",
      "decision": "SOL",
      "reason": "SOL keeps the thought that the current dream might resemble those memories."
    },
    {
      "hunk_id": "H097",
      "decision": "SOL",
      "reason": "SOL preserves the overhead birdcall interrupting his thought."
    },
    {
      "hunk_id": "H098",
      "decision": "SOL",
      "reason": "SOL keeps the contrast between the present and the dream’s illusory quality."
    },
    {
      "hunk_id": "H099",
      "decision": "SOL",
      "reason": "“Now’s not the time” keeps the brief self-reminder."
    },
    {
      "hunk_id": "H100",
      "decision": "SOL",
      "reason": "SOL preserves the small head shake and the drawing up of Scorching Yang Qi."
    },
    {
      "hunk_id": "H101",
      "decision": "BASE",
      "reason": "SOL replaces the source’s “tuduk” sound with “drip.”"
    },
    {
      "hunk_id": "H102",
      "decision": "BASE",
      "reason": "SOL invents drops falling away; the source only gives a sound effect as the clothes dry."
    },
    {
      "hunk_id": "H103",
      "decision": "SOL",
      "reason": "“There’s that way too” preserves Mujin’s realization."
    },
    {
      "hunk_id": "H104",
      "decision": "BASE",
      "reason": "SOL drops the teasing “unlike you” jab."
    },
    {
      "hunk_id": "H105",
      "decision": "SOL",
      "reason": "“Showing off” naturally conveys the question about bragging."
    },
    {
      "hunk_id": "H106",
      "decision": "SOL",
      "reason": "SOL keeps Mujin’s resigned concession."
    },
    {
      "hunk_id": "H107",
      "decision": "BASE",
      "reason": "SOL shortens the established name Hyuk Mujin to “Mujin.”"
    },
    {
      "hunk_id": "H108",
      "decision": "BASE",
      "reason": "SOL drops the skyward look and the source’s unthinking reaction."
    },
    {
      "hunk_id": "H109",
      "decision": "SOL",
      "reason": "SOL keeps the prompt widening of his eyes."
    },
    {
      "hunk_id": "H110",
      "decision": "SOL",
      "reason": "SOL preserves the blood-soaked missive tied to the falcon’s leg as it glides overhead."
    }
  ]
}

